const ri = (($('Read Input as-U').first() || {}).json) || {};
const blocks = Array.isArray(ri.blocks) ? ri.blocks : [];
const riWarnings = Array.isArray(ri.warnings) ? ri.warnings : [];
const up = (($('Upload Images').first() || {}).json) || {};
const fileMap = Array.isArray(up.file_map) ? up.file_map : [];
const wc = (($('When Called').first() || {}).json) || {};
const taskId = wc.clickup_task_id || ri.clickup_task_id || '';
const denied = riWarnings.some(function(w){ return w && w.source === 'clickup-asU/access-denied'; });
if (denied) {
  return [{ json: {
    status: 'denied',
    tool_result_content_json: JSON.stringify([{ type: 'text', text: 'Brak dostepu: nie masz uprawnien do zadania ' + taskId + ' w ClickUp (albo zadanie nie istnieje). Nie pobrano zadnej tresci.' }]),
    new_warnings_json: '[]',
    new_images_json: '[]'
  } }];
}
const fileById = {};
for (const f of fileMap) { if (f && f.file_id) { if (f.order != null) fileById['o:' + f.order] = f.file_id; if (f.source_ref != null) fileById['s:' + f.source_ref] = f.file_id; if (f.url) fileById['r:' + f.url] = f.file_id; } }
const sorted = blocks.slice().sort(function(a, b){ return ((a && a.order) || 0) - ((b && b.order) || 0); });
const body = [];
let docCount = 0, imgCount = 0, imgFailed = 0;
for (const b of sorted) {
  if (!b) continue;
  if (b.type === 'text') {
    const md = b.md || '';
    if (md) { body.push({ type: 'text', text: md }); if (md.indexOf('[BRAK') !== 0) docCount++; }
  } else if (b.type === 'image') {
    const fid = fileById['o:' + b.order] || (b.source_ref != null ? fileById['s:' + b.source_ref] : null) || (b.ref ? fileById['r:' + b.ref] : null);
    if (fid) { body.push({ type: 'image', source: { type: 'file', file_id: fid } }); imgCount++; }
    else { imgFailed++; body.push({ type: 'text', text: '[obraz niedostepny: ' + (b.alt || b.source_ref || '') + ']' }); }
  }
}
const header = 'Wyekstrahowano zawartosc zalacznikow zadania ' + taskId + ': ' + docCount + ' dok., ' + imgCount + ' obr.' + (imgFailed ? (' (' + imgFailed + ' obr. nie pobrano)') : '') + (body.length === 0 ? ' Brak zalacznikow do ekstrakcji.' : '');
const content = [{ type: 'text', text: header }].concat(body);
const warnings = [];
for (const w of riWarnings) { if (w && w.source !== 'clickup-asU/access-denied') warnings.push({ source: 'managed-agents/extract-readinput', err: ((w.title ? w.title + ': ' : '') + (w.err || w.source || '')).slice(0, 300), severity: 'WARN' }); }
for (const w of (Array.isArray(up.warnings) ? up.warnings : [])) warnings.push({ source: 'managed-agents/extract-upload', err: String((w && (w.err || w.warn_source)) || '').slice(0, 300), severity: 'WARN' });
return [{ json: {
  status: (imgFailed > 0 || warnings.length > 0) ? 'partial' : 'ok',
  tool_result_content_json: JSON.stringify(content),
  new_warnings_json: JSON.stringify(warnings),
  new_images_json: '[]'
} }];

const wc = (($('When Called').first() || {}).json) || {};
const scope = wc.clickup_scope || '';
const uid = wc.caller_user_id || '?';
const warnings = [];
if (scope === 'scoped') {
  warnings.push({ source: 'managed-agents/extract-no-rest-token', err: 'Uzytkownik ' + uid + ' ma poswiadczenie ClickUp do wyszukiwania (discovery), ale BRAK tokenu REST do ekstrakcji zalacznikow - dokoncz onboarding (token REST w Supabase Vault).', severity: 'WARN' });
}
return [{ json: {
  status: 'unavailable',
  tool_result_content_json: JSON.stringify([{ type: 'text', text: 'Narzedzie ekstrakcji zalacznikow jest niedostepne dla Twojego konta (brak poswiadczenia ClickUp). Pracuj na podstawie dostarczonego kontekstu i nie zglaszaj tego jako bledu.' }]),
  new_warnings_json: JSON.stringify(warnings),
  new_images_json: '[]'
} }];
